import { error } from "@sveltejs/kit";
import {
  getTopNavigation,
  type CompiledContentArtifact,
  type Sidebar,
} from "@docsfn/core";
import {
  resolveDocsPageSurface,
  resolveDocsRouteDataOrThrow,
  type SvelteDocsPageSurface,
} from "@docsfn/sveltekit";
import type { DocsSiteSource } from "./runtime";

interface DocsPageOptions {
  apiBreadcrumbLabel?: string;
  apiBreadcrumbHref?: string;
  fallbackSidebarId?: string;
}

function buildCanonicalUrl(canonicalBase: string | undefined, path: string): string {
  if (!canonicalBase) return path;
  const origin = canonicalBase.replace(/\/+$/, "");
  return `${origin}${path.startsWith("/") ? path : `/${path}`}`;
}

function isRouteNotFoundError(input: unknown): input is { message: string } {
  return (
    typeof input === "object" && input !== null &&
    "code" in input && input.code === "DOCS_ROUTE_NOT_FOUND" &&
    "message" in input && typeof input.message === "string"
  );
}

function hasNestedDocsRoutes(routes: Record<string, string>, route: string): boolean {
  return Object.keys(routes).some((candidate) => candidate.startsWith(`${route}/`));
}

export async function loadDocsPage(input: {
  slug: string | undefined;
  source: DocsSiteSource;
  getCompiledDocsPage: (id: string) => Promise<CompiledContentArtifact>;
  resolveMarkdownRelativeLinks: (input: {
    compiled: CompiledContentArtifact;
    route: string;
    sourcePath: string;
    isIndexRoute: boolean;
  }) => CompiledContentArtifact;
  options?: DocsPageOptions;
}) {
  const { slug, source, getCompiledDocsPage, resolveMarkdownRelativeLinks, options = {} } = input;
  let routeEntry;
  try {
    routeEntry = resolveDocsRouteDataOrThrow(slug, source.manifest, { basePath: "/docs" });
  } catch (routeError) {
    if (isRouteNotFoundError(routeError)) throw error(404, routeError.message);
    throw routeError;
  }

  if (routeEntry.kind === "post") {
    throw error(404, `unsupported docs route kind: ${routeEntry.kind}`);
  }

  let surface: SvelteDocsPageSurface;
  if (routeEntry.kind === "api") {
    const api = routeEntry.api;
    const route = routeEntry.route;
    surface = {
      route,
      title: api.title,
      description: typeof api.frontmatter.description === "string" ? api.frontmatter.description : undefined,
      canonicalPath: route,
      canonicalUrl: buildCanonicalUrl(source.canonicalUrl, route),
      sidebarId: "api",
      headings: [],
      breadcrumbs: [
        { label: "Docs", href: "/docs" },
        { label: options.apiBreadcrumbLabel ?? "API Reference", href: options.apiBreadcrumbHref ?? "/docs/api" },
        { label: api.title, href: route },
      ],
      pagination: {},
      topNav: getTopNavigation(source.manifest),
      versions: source.manifest.versions,
    };
  } else {
    surface = resolveDocsPageSurface({
      manifest: source.manifest,
      route: routeEntry.route,
      page: routeEntry.page,
      options: {
        basePath: "/docs",
        homeHref: "/docs",
        canonicalUrl: source.canonicalUrl,
        versionMode: "path-prefix",
      },
    });
  }

  const sidebarId = surface.sidebarId ?? "default";
  const sidebar: Sidebar | undefined = source.manifest.sidebars[sidebarId] ??
    (options.fallbackSidebarId ? source.manifest.sidebars[options.fallbackSidebarId] : undefined);
  const compiled = routeEntry.kind === "page"
    ? resolveMarkdownRelativeLinks({
        compiled: await getCompiledDocsPage(routeEntry.page.id),
        route: routeEntry.route,
        sourcePath: routeEntry.page.id.replace(/^docs:/, ""),
        isIndexRoute: hasNestedDocsRoutes(source.manifest.routes, routeEntry.route),
      })
    : undefined;

  return {
    routeEntry,
    surface,
    sidebar,
    compiled,
    searchDocumentCount: Array.isArray(source.searchArtifact.documents) ? source.searchArtifact.documents.length : 0,
    searchScopes: Array.isArray(source.searchArtifact.scopes) ? source.searchArtifact.scopes.join(", ") : "none",
    siteTitle: source.siteTitle,
    compatPreset: source.compatPreset,
  };
}

import { basename, extname } from "node:path";
import matter from "gray-matter";
import {
  assertValidSourceEntries,
  buildManifest,
  buildSearchIndex,
  compileSvelteContent,
  createDiagnostic,
  createDocsError,
  createSourceEntryId,
  createDocsSearchRuntime,
  normalizeProviderPath,
  toLegacyRawEntries,
  type CompiledContentArtifact,
  type DocsCollection,
  type DocsCompatPreset,
  type DocsConfig,
  type DocsContentProvider,
  type DocsManifest,
  type DocsSearchArtifact,
  type DocsSearchRuntime,
  type DocsSourceEntry,
} from "@docsfn/core";

export interface DocsSiteSource {
  siteRoot: string;
  manifest: DocsManifest;
  searchArtifact: DocsSearchArtifact;
  siteTitle: string;
  canonicalUrl?: string;
  compatPreset: DocsCompatPreset;
  config: DocsConfig;
}

export interface DocsSiteCompiledCacheSummary {
  framework: "svelte";
  compatPreset: DocsCompatPreset;
  pageKeys: string[];
  postKeys: string[];
}

interface DocsSiteCompiledContentCache {
  framework: "svelte";
  compatPreset: DocsCompatPreset;
  pages: Map<string, CompiledContentArtifact>;
  posts: Map<string, CompiledContentArtifact>;
  pageKeysById: Record<string, string>;
  postKeysById: Record<string, string>;
}

interface DocsSiteServerState {
  source: DocsSiteSource;
  compiledCache: DocsSiteCompiledContentCache;
}

function createCompiledCacheKey(input: {
  kind: "page" | "post";
  id: string;
  framework: "svelte";
  compatPreset: DocsCompatPreset;
}): string {
  return [input.kind, input.id, input.framework, input.compatPreset].join("|");
}

function sortById<T extends { id: string }>(items: T[]): T[] {
  return [...items].sort((left, right) =>
    left.id.localeCompare(right.id, "en", {
      sensitivity: "variant",
      numeric: true,
    }),
  );
}

function createCompiledCache(input: {
  manifest: DocsManifest;
  compatPreset: DocsCompatPreset;
}): DocsSiteCompiledContentCache {
  const framework = "svelte" as const;
  const pages = new Map<string, CompiledContentArtifact>();
  const posts = new Map<string, CompiledContentArtifact>();
  const pageKeysById: Record<string, string> = {};
  const postKeysById: Record<string, string> = {};

  for (const page of sortById(Object.values(input.manifest.pages))) {
    const key = createCompiledCacheKey({
      kind: "page",
      id: page.id,
      framework,
      compatPreset: input.compatPreset,
    });
    pageKeysById[page.id] = key;
    pages.set(
      key,
      compileSvelteContent({
        source: page.body,
        sourcePath: page.id,
        compatPreset: input.compatPreset,
      }),
    );
  }

  for (const post of sortById(Object.values(input.manifest.posts))) {
    const key = createCompiledCacheKey({
      kind: "post",
      id: post.id,
      framework,
      compatPreset: input.compatPreset,
    });
    postKeysById[post.id] = key;
    posts.set(
      key,
      compileSvelteContent({
        source: post.body,
        sourcePath: post.id,
        compatPreset: input.compatPreset,
      }),
    );
  }

  return {
    framework,
    compatPreset: input.compatPreset,
    pages,
    posts,
    pageKeysById,
    postKeysById,
  };
}

function getCompiledArtifactOrThrow(input: {
  kind: "page" | "post";
  id: string;
  cache: DocsSiteCompiledContentCache;
}): CompiledContentArtifact {
  const keysById =
    input.kind === "page" ? input.cache.pageKeysById : input.cache.postKeysById;
  const entries = input.kind === "page" ? input.cache.pages : input.cache.posts;
  const key = keysById[input.id];

  if (!key) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: `compiled ${input.kind} cache key is missing for ${input.id}`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: `compiled ${input.kind} cache key is missing for ${input.id}`,
          details: {
            kind: input.kind,
            id: input.id,
          },
        }),
      ],
    });
  }

  const compiled = entries.get(key);
  if (!compiled) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: `compiled ${input.kind} artifact is missing for ${input.id}`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: `compiled ${input.kind} artifact is missing for ${input.id}`,
          details: {
            kind: input.kind,
            id: input.id,
            key,
          },
        }),
      ],
    });
  }

  return compiled;
}

/** One independent cache per site; raw modules are supplied by the site's Vite glob. */
export function createDocsSiteRuntime(
  docsConfig: DocsConfig,
  bundledContent: Record<string, string>,
  bundledStatic: Record<string, string>,
  modulePrefix = "../../../",
) {
  let serverStatePromise: Promise<DocsSiteServerState> | null = null;
  async function loadDocsSiteServerState(): Promise<DocsSiteServerState> {
    serverStatePromise ??= (async () => {
        const siteRoot = ".";
        const config = docsConfig satisfies DocsConfig;
        const provider = createBundledContentProvider(config);
        const manifest = await buildManifest(provider, config);
        const searchArtifact = await buildSearchIndex(manifest, {
          search: config.search,
          auth: config.auth,
        });
        const compatPreset = config.compat?.preset ?? "none";
        const compiledCache = createCompiledCache({
          manifest,
          compatPreset,
        });

        return {
          source: {
            siteRoot,
            manifest,
            searchArtifact,
            siteTitle: config.site.title,
            canonicalUrl: config.site.canonicalUrl,
            compatPreset,
            config,
          },
          compiledCache,
        };
    })().catch((error) => {
      serverStatePromise = null;
      throw error;
    });

    return serverStatePromise;
  }

  async function loadDocsSiteSource(): Promise<DocsSiteSource> {
    const state = await loadDocsSiteServerState();
    return state.source;
  }

  async function getCompiledDocsPage(
    pageId: string,
  ): Promise<CompiledContentArtifact> {
    const state = await loadDocsSiteServerState();
    return getCompiledArtifactOrThrow({
      kind: "page",
      id: pageId,
      cache: state.compiledCache,
    });
  }

  async function getCompiledDocsPost(
    postId: string,
  ): Promise<CompiledContentArtifact> {
    const state = await loadDocsSiteServerState();
    return getCompiledArtifactOrThrow({
      kind: "post",
      id: postId,
      cache: state.compiledCache,
    });
  }

  async function getDocsSiteCompiledCacheSummary(): Promise<DocsSiteCompiledCacheSummary> {
    const state = await loadDocsSiteServerState();
    return {
      framework: state.compiledCache.framework,
      compatPreset: state.compiledCache.compatPreset,
      pageKeys: [...state.compiledCache.pages.keys()].sort((left, right) =>
        left.localeCompare(right, "en", {
          sensitivity: "variant",
          numeric: true,
        }),
      ),
      postKeys: [...state.compiledCache.posts.keys()].sort((left, right) =>
        left.localeCompare(right, "en", {
          sensitivity: "variant",
          numeric: true,
        }),
      ),
    };
  }

  async function createDocsSiteSearchRuntime(): Promise<DocsSearchRuntime> {
    const state = await loadDocsSiteServerState();
    return createDocsSearchRuntime({
      artifact: state.source.searchArtifact,
    });
  }

  function createBundledContentProvider(
    config: DocsConfig,
  ): DocsContentProvider {
    const modules = {
      ...normalizeBundledModules(bundledContent, modulePrefix),
      ...normalizeBundledModules(bundledStatic, modulePrefix),
    };

    return {
      providerId: "bundled",
      async listEntries(input) {
        const entries = input.collections.flatMap((collection) =>
          collectEntriesForCollection(collection, modules, config),
        );
        return assertValidSourceEntries(entries);
      },
      async loadEntry(input) {
        return input.entry;
      },
      async list() {
        const entries = await this.listEntries({
          config,
          collections: ["docs", "pages", "blog", "api", "assets"],
        });
        return toLegacyRawEntries(entries);
      },
    };
  }

  return {
    loadDocsSiteSource,
    getCompiledDocsPage,
    getCompiledDocsPost,
    getDocsSiteCompiledCacheSummary,
    createDocsSiteSearchRuntime,
  };
}

function normalizeBundledModules(
  modules: Record<string, string>,
  prefix: string,
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(modules).map(([modulePath, source]) => [
      normalizeProviderPath(modulePath.replace(prefix, "")),
      source,
    ]),
  );
}

function isMarkdownCollection(collection: DocsCollection): collection is Extract<DocsCollection, "docs" | "pages" | "blog"> {
  return ["docs", "pages", "blog"].includes(collection);
}

function collectEntriesForCollection(
  collection: DocsCollection,
  modules: Record<string, string>,
  config: DocsConfig,
): DocsSourceEntry[] {
  const directory = collectionDirectory(collection, config);
  const entries: DocsSourceEntry[] = [];

  for (const [modulePath, source] of Object.entries(modules)) {
    if (modulePath !== directory && !modulePath.startsWith(`${directory}/`)) {
      continue;
    }

    const relativePath = normalizeProviderPath(
      modulePath.slice(directory.length + 1),
    );
    if (!relativePath || relativePath === ".gitkeep") {
      continue;
    }

    const entry = createEntryForModule(collection, relativePath, source, modulePath, config);
    if (entry) entries.push(entry);
  }

  return entries.sort((left, right) =>
    left.id.localeCompare(right.id, "en", {
      sensitivity: "variant",
      numeric: true,
    }),
  );
}

function createEntryForModule(
  collection: DocsCollection,
  relativePath: string,
  source: string,
  modulePath: string,
  config: DocsConfig,
): DocsSourceEntry | undefined {
  const extension = extname(relativePath).toLowerCase();
  const fileName = basename(relativePath).toLowerCase();

  if (fileName === (config.content.metaFileName ?? "meta.json").toLowerCase()) {
    return createControlEntry(collection, relativePath, source, modulePath);
  }
  if (collection === "assets") {
    return createAssetEntry(relativePath, source, modulePath);
  }
  if (isMarkdownCollection(collection) && [".md", ".mdx"].includes(extension)) {
    return createMarkdownEntry(collection, relativePath, source, modulePath);
  }
  if (collection === "api" && [".json", ".yaml", ".yml"].includes(extension)) {
    return createApiEntry(relativePath, source, modulePath);
  }
}

function collectionDirectory(
  collection: DocsCollection,
  config: DocsConfig,
): string {
  if (collection === "docs") return config.content.docsDir ?? "content/docs";
  if (collection === "pages") return config.content.pagesDir ?? "content/pages";
  if (collection === "blog") return config.content.blogDir ?? "content/blog";
  if (collection === "api") return config.content.apiDir ?? "content/api";
  return config.content.assetsDir ?? "static";
}

function createMarkdownEntry(
  collection: Extract<DocsCollection, "docs" | "pages" | "blog">,
  relativePath: string,
  source: string,
  sourcePath: string,
): DocsSourceEntry {
  const parsed = parseFrontmatter(source);
  return {
    id: createSourceEntryId(collection, relativePath),
    collection,
    relativePath,
    absolutePath: sourcePath,
    entryType: "content",
    body: parsed.body,
    frontmatter: {
      title: deriveTitleFromPath(relativePath),
      ...parsed.frontmatter,
    },
    bytes: byteLength(source),
    meta: {
      extension: extname(relativePath).toLowerCase(),
    },
  };
}

function createControlEntry(
  collection: DocsCollection,
  relativePath: string,
  source: string,
  sourcePath: string,
): DocsSourceEntry {
  return {
    id: createSourceEntryId(collection, relativePath),
    collection,
    relativePath,
    absolutePath: sourcePath,
    entryType: "control",
    body: source,
    frontmatter: {},
    bytes: byteLength(source),
    meta: {
      controlFile: true,
      parsed: parseJson(source),
    },
  };
}

function createApiEntry(relativePath: string, source: string, sourcePath: string): DocsSourceEntry {
  return {
    id: createSourceEntryId("api", relativePath),
    collection: "api",
    relativePath,
    absolutePath: sourcePath,
    entryType: "content",
    body: source,
    frontmatter: {
      title: deriveTitleFromPath(relativePath),
    },
    bytes: byteLength(source),
    meta: {
      extension: extname(relativePath).toLowerCase(),
    },
  };
}

function createAssetEntry(
  relativePath: string,
  source: string,
  sourcePath: string,
): DocsSourceEntry {
  return {
    id: createSourceEntryId("assets", relativePath),
    collection: "assets",
    relativePath,
    absolutePath: sourcePath,
    entryType: "asset",
    frontmatter: {},
    bytes: byteLength(source),
  };
}

function parseFrontmatter(source: string): {
  body: string;
  frontmatter: Record<string, unknown>;
} {
  const parsed = matter(source);
  return { body: parsed.content, frontmatter: parsed.data };
}

function parseJson(source: string): unknown {
  try {
    return JSON.parse(source);
  } catch {
    return null;
  }
}

function deriveTitleFromPath(relativePath: string): string {
  return basename(relativePath)
    .replace(/\.[^/.]+$/, "")
    .split(/[-_]/g)
    .map((segment) =>
      segment.length > 0
        ? `${segment.charAt(0).toUpperCase()}${segment.slice(1)}`
        : segment,
    )
    .join(" ");
}

function byteLength(source: string): number {
  return new TextEncoder().encode(source).byteLength;
}

import { defineConfig } from "vitest/config";
import { pathToFileURL, fileURLToPath } from "node:url";
import { resolve } from "node:path";
import { readFileSync } from "node:fs";
import { docsSiteCorePlugin } from "./vite";

const sitePackagePath = resolve(process.cwd(), "package.json");
const sitePackage = JSON.parse(readFileSync(sitePackagePath, "utf8"));
if (!sitePackage.name?.endsWith("/docs") || !sitePackage.dependencies?.["@docsfn/core"]) {
  throw new Error("Run DocsFn site tests from a consuming docs workspace, for example npm test --workspace @botfn/docs");
}

export default defineConfig({
  plugins: [docsSiteCorePlugin(pathToFileURL(sitePackagePath).href)],
  test: { root: fileURLToPath(new URL(".", import.meta.url)), include: ["runtime.test.ts"] },
});

